import { NeonWidgetSlotted } from '../shared/neon-widget-slotted';
import { dynamicText, createElement, updateDynamicText, updateDynamicAttribute, dynamicAttr, registerComponent } from '../shared/dom-manipulation';
import { translate, addTranslationListener } from '@ps-refarch-ux/mfe-utils';
export class NeonErrorCardContent extends NeonWidgetSlotted {
    constructor() {
        super(...arguments);
        this.widgetTag = 'neon-error-card-content';
    }
    //Any attribute that should be watched for changes should be listed here.
    static get observedAttributes() {
        return [
            'data-illustration',
            'data-error-text'
        ];
    }
    //when the attributes change this will run
    attributeChanged(attrName, oldVal, newVal) {
        super.attributeChanged(attrName, oldVal, newVal);
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        switch (attrName) {
            case 'data-illustration':
                updateDynamicAttribute(this, 'data-illustration');
                break;
            case 'data-error-text':
                updateDynamicText(this);
                break;
            default:
        }
    }
    getErrorText() {
        const errorText = this.getAttribute('data-error-text');
        if (errorText != null) {
            return errorText;
        }
        else {
            return translate('neon|error-card-content|text|The information could not be found. Click Refresh to try again.');
        }
    }
    render() {
        return createElement('div', {
            attrs: {
                class: 'neon-error-card-content'
            },
        }, ...this.getSlotElse('error-card-content-media', () => {
            return createElement('neon-2_20_1-illustration', {
                attrs: {
                    class: 'neon-error-card-content-illustration',
                    'data-illustration': dynamicAttr(() => { return this.getAttribute('data-illustration') != null ? this.getAttribute('data-illustration') : 'paper-airplane'; }),
                    'data-background': 'complex',
                },
            });
        }), createElement('p', {
            text: dynamicText(() => { return this.getErrorText(); }),
            attrs: {
                class: 'neon-error-card-content-text'
            }
        }), this.getSlot('card-error-buttons'));
    }
    connectedCallback() {
        super.connectedCallback();
        this.i18nUnsubscribe = addTranslationListener(() => {
            updateDynamicText(this);
        });
    }
    disconnectedCallback() {
        if (this.i18nUnsubscribe != null) {
            this.i18nUnsubscribe();
            this.i18nUnsubscribe = undefined;
        }
    }
}
export function registerNeonErrorCardContent() {
    registerComponent('neon-2_20_1-error-card-content', NeonErrorCardContent);
}
